import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as i,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Testing AI 教程（Midscene）","description":"按 Midscene 官方文档把视觉 UI 测试接到 Playwright。不编造 npm 包名以外的 API。","frontmatter":{"title":"Testing AI 教程（Midscene）","description":"按 Midscene 官方文档把视觉 UI 测试接到 Playwright。不编造 npm 包名以外的 API。","domain":"product","tags":["testing"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/testing-ai/testing-ai.md","filePath":"zh/products/testing-ai/testing-ai.md","lastUpdated":1787110548000}'),n={name:"zh/products/testing-ai/testing-ai.md"};function o(s,e,l,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="testing-ai-教程-midscene" tabindex="-1">Testing AI 教程（Midscene） <a class="header-anchor" href="#testing-ai-教程-midscene" aria-label="Permalink to &quot;Testing AI 教程（Midscene）&quot;">​</a></h1><blockquote><p>本页主路径是 <strong>Midscene</strong>。官方：<a href="https://midscenejs.com/introduction" target="_blank" rel="noreferrer">Introduction</a>、<a href="https://midscenejs.com/integrate-with-playwright" target="_blank" rel="noreferrer">Integrate with Playwright</a>、<a href="https://github.com/web-infra-dev/midscene" target="_blank" rel="noreferrer">GitHub</a>。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>你会完成：</strong> 知道 Midscene 和 DOM 选择器方案差在哪，打开官方 Playwright 集成页做第一次接入。</p><p><strong>不会做：</strong> 把仓库旧文里的 ZeroStep <code>ai()</code> 示例当现行官方 API；给 Qodo 写安装。</p><h2 id="midscene-是什么-官方原文" tabindex="-1">Midscene 是什么（官方原文） <a class="header-anchor" href="#midscene-是什么-官方原文" aria-label="Permalink to &quot;Midscene 是什么（官方原文）&quot;">​</a></h2><p>Introduction：</p><ul><li>开源 SDK，视觉驱动 UI 测试与自动化。</li><li><strong>只靠截图</strong>，用多模态模型；用自然语言写目标和断言。</li><li><strong>两种用法：</strong> 加进现有 Playwright / Vitest，或让 Agent 通过 Skills 自主测。</li><li>方法名在官方 API 里：<code>aiAct</code>、<code>aiQuery</code>、<code>aiAssert</code> 等（以 <a href="https://midscenejs.com/introduction" target="_blank" rel="noreferrer">API reference</a> 链出去的 reference 为准）。</li></ul><p>不要把旧摘抄里的 <code>await ai(&#39;Navigate to booking page&#39;)</code> 写成 Midscene 现行 API。</p><h2 id="接到-playwright" tabindex="-1">接到 Playwright <a class="header-anchor" href="#接到-playwright" aria-label="Permalink to &quot;接到 Playwright&quot;">​</a></h2><p>逐步命令、fixture 名以官方 <a href="https://midscenejs.com/integrate-with-playwright" target="_blank" rel="noreferrer">Integrate with Playwright</a> 为准。该页还链示例仓库 <code>web-infra-dev/midscene-example</code>。</p> 本页不抄一份可能过期的 `npm i` 包名表；打开上面官方页复制。 <p>示例项目（官方页原文）：</p><ul><li>直接集成：<a href="https://github.com/web-infra-dev/midscene-example/blob/main/playwright-demo" target="_blank" rel="noreferrer">https://github.com/web-infra-dev/midscene-example/blob/main/playwright-demo</a></li><li>Playwright test：<a href="https://github.com/web-infra-dev/midscene-example/blob/main/playwright-testing-demo" target="_blank" rel="noreferrer">https://github.com/web-infra-dev/midscene-example/blob/main/playwright-testing-demo</a></li></ul><h2 id="目录里其它工具" tabindex="-1">目录里其它工具 <a class="header-anchor" href="#目录里其它工具" aria-label="Permalink to &quot;目录里其它工具&quot;">​</a></h2><ul><li><strong>Qodo</strong>：原 Codium。官网定位已是 AI code review 平台，不是「只写单测的插件」。去 <a href="https://www.qodo.ai/" target="_blank" rel="noreferrer">qodo.ai</a>。</li><li><strong>ZeroStep / Reflect</strong>：地图一行。2026-08-19 未把它们的安装命令核进本 Tutorial。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./testing-ai-cheatsheet.html">速查</a> · 本站技术笔记 <a href="/zh/tech/testing/midscene-ui-automation.html">Midscene UI 自动化</a></p>',18)])])}const b=t(n,[["render",o]]);export{f as __pageData,b as default};
